package io.nikhil.cqrsbankaccount.command.api.commands

import io.nikhil.cqrsbankaccount.common.dtos.AccountType
import java.math.BigDecimal

/**
 * Opens a new account.
 *
 * @property accountId the new account's id, generated by the server.
 * @property accountHolder the name of the account holder; leading and trailing whitespace is removed.
 * @property accountType the kind of account to open.
 * @property openingBalance the initial balance; must not be negative.
 * @property idempotencyKey optional client key that makes retries of this command safe. A retry returns
 *   the account opened by the original command, not a new one.
 */
data class OpenAccountCommand(
    override val accountId: String,
    val accountHolder: String,
    val accountType: AccountType,
    val openingBalance: BigDecimal = BigDecimal.ZERO,
    override val idempotencyKey: String? = null,
) : AccountCommand()
